import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.B8xISX-C.js";const h=JSON.parse('{"title":"race-picks","description":"","frontmatter":{},"headers":[],"relativePath":"reference/race-picks.md","filePath":"reference/race-picks.md"}'),c={name:"reference/race-picks.md"};function s(i,e,r,l,n,f){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="race-picks" tabindex="-1">race-picks <a class="header-anchor" href="#race-picks" aria-label="Permalink to &quot;race-picks&quot;">​</a></h1><p>A race pick: a trait level or a special ability, made of race effects.</p><p>A mod adds records in <code>records/race-picks/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;race-picks&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>race-picks</code>. Schema: <a href="/carina-mod-template/schemas/records/race-picks.schema.json">race-picks records schema</a>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-group" class="field-name"><code>group</code></span><a class="field-link" href="#f-group" aria-label="Link to group">#</a></td><td>one of <code>trait</code>, <code>government</code>, <code>special</code></td><td>yes</td><td></td></tr><tr><td><span id="f-trait" class="field-name"><code>trait</code></span><a class="field-link" href="#f-trait" aria-label="Link to trait">#</a></td><td>one of <code>population</code>, <code>farming</code>, <code>industry</code>, <code>science</code>, <code>money</code>, <code>shipDefense</code>, <code>shipAttack</code>, <code>groundCombat</code>, <code>spying</code> or null</td><td>yes</td><td></td></tr><tr><td><span id="f-level" class="field-name"><code>level</code></span><a class="field-link" href="#f-level" aria-label="Link to level">#</a></td><td>one of <code>penalty</code>, <code>bonus</code>, <code>bigBonus</code> or null</td><td>yes</td><td></td></tr><tr><td><span id="f-cost" class="field-name"><code>cost</code></span><a class="field-link" href="#f-cost" aria-label="Link to cost">#</a></td><td>integer</td><td>yes</td><td></td></tr><tr><td><span id="f-value" class="field-name"><code>value</code></span><a class="field-link" href="#f-value" aria-label="Link to value">#</a></td><td>integer or null</td><td>yes</td><td></td></tr><tr><td><span id="f-valueUnit" class="field-name"><code>valueUnit</code></span><a class="field-link" href="#f-valueUnit" aria-label="Link to valueUnit">#</a></td><td>one of <code>pct</code>, <code>halfFood</code>, <code>halfBc</code>, <code>perWorker</code>, <code>points</code> or null</td><td>yes</td><td></td></tr><tr><td><span id="f-government" class="field-name"><code>government</code></span><a class="field-link" href="#f-government" aria-label="Link to government">#</a></td><td>snake_case key or null</td><td>yes</td><td></td></tr><tr><td><span id="f-exclusiveWith" class="field-name"><code>exclusiveWith</code></span><a class="field-link" href="#f-exclusiveWith" aria-label="Link to exclusiveWith">#</a></td><td>list of snake_case keys (no repeats)</td><td>yes</td><td></td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-descKey" class="field-name"><code>descKey</code></span><a class="field-link" href="#f-descKey" aria-label="Link to descKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-effects" class="field-name"><code>effects</code></span><a class="field-link" href="#f-effects" aria-label="Link to effects">#</a></td><td>list of effects (<a href="./effects">Effects</a>)</td><td>no</td><td></td></tr></tbody></table><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><p>Nothing else: the record works on its own.</p><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>Computer races use the picks of their race records; the AI&#39;s mutation order is the race-rules <code>aiMutationOrder</code> list.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Only special picks can be added: every trait level is taken, and governments are closed. Column three of the custom race screen pages when it holds more than 22 picks.</li><li>The screens label a pick <code>ui.raceCustom.option.&lt;key&gt;</code> and <code>ui.raceSelect.pick.&lt;key&gt;</code>: the mod&#39;s English text needs both.</li><li>Effects come from the race effect list (<a href="./effects">Effects</a>).</li><li>The pick&#39;s description (<code>descKey</code>) is plain text: a mod&#39;s own text keys take no ICU arguments (the base&#39;s pick texts do, read from the record), so write the numbers into the text and keep them equal to the record&#39;s <code>effects</code> when you change either. Give it no <code>Name:</code> prefix: the screens show the pick&#39;s name beside it.</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>cost</code>, <code>descKey</code>, <code>effects</code>, <code>exclusiveWith</code>, <code>government</code>, <code>group</code>, <code>level</code>, <code>nameKey</code>, <code>trait</code>, <code>value</code>, <code>valueUnit</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: <code>effects</code>, <code>exclusiveWith</code></li></ul>',15)])])}const u=t(c,[["render",s]]);export{h as __pageData,u as default};
